{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "MESA item 14: missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score provides no evidence of variation across runs."
        }
      ],
      "instrument_review": "MESA item 14 is Not sure. Repeated testing and score stability remain unestablished."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run establishes neither stability nor instability across runs."
        }
      ],
      "instrument_review": "MESA item 14 is No because repetition explicitly did not occur. Stability remains unknown."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing measured scores under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The two-percentage-point range meets the report's stated stability criterion."
        }
      ],
      "instrument_review": "MESA item 14 is Yes. The observed variation supports stability for this comparison under its explicit definition."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing occurred regardless of whether results were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's maximum of two percentage points for stability."
        }
      ],
      "instrument_review": "MESA item 14 is Yes because variation was tested. The findings contradict stability under the stated criterion."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation documentation supplies no evidence that repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no measurements of variation across runs."
        }
      ],
      "instrument_review": "MESA item 14 remains Not sure. Installation instructions contribute to documentation relevant to item 22, but do not establish score consistency."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "With exact-grid scoring, A performed better in the reported grid evaluation."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA items 20 and 25 distinguish the supported grid comparison from unsupported extrapolation. The stated intended use stays within the evaluated tasks."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved the better result on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use does not supply evidence of performance across domains."
        }
      ],
      "instrument_review": "MESA items 9, 20 and 25 raise a mismatch between the narrow evidence and the intended general-intelligence selection. The grid comparison remains supported."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence supplies no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial and difference interval of 12 to 28 percentage points support better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness results do not establish an effect on an unmeasured safety outcome."
        }
      ],
      "instrument_review": "MESA item 20 gains direct evidence for workshop decision correctness from the later trial. Item 16 is supported by the reported difference interval. Item 25 requires limiting conclusions to correctness in the studied workshop and conditions."
    }
  ],
  "closing_note": "No instructions required clarification. Probe labels classify statements; MESA testing judgments concern whether testing occurred, not whether results were favourable."
}
